create extension if not exists pgcrypto;
create type public.user_state as enum ('NEW_USER','ONBOARDING','BUILDING_BASELINE','BASELINE_READY','IMPROVEMENT_ACTIVE','WAITING_FOR_MORE_RECORDS','RESULT_READY','DATA_DELETION_PENDING');
create type public.improvement_type as enum ('SCOOP_MORE','CHANGE_LITTER','ADD_LITTER_BOX','MOVE_LITTER_BOX','IMPROVE_VENTILATION','CLEAN_LITTER_BOX','OTHER');
create type public.special_event_type as enum ('JUST_SCOOPED','JUST_CHANGED_LITTER','JUST_CLEANED_BOX','HUMID_WEATHER','AWAY_LONG_TIME','GUESTS','OTHER');
create type public.time_bucket as enum ('MORNING','AFTERNOON','EVENING','NIGHT');
create table public.users(id uuid primary key default gen_random_uuid(),auth_user_id uuid unique references auth.users(id) on delete set null,line_user_id_hash text unique not null,line_user_id_encrypted text not null,state public.user_state not null default 'NEW_USER',locale text not null default 'zh-TW',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.households(id uuid primary key default gen_random_uuid(),user_id uuid unique not null references public.users(id) on delete cascade,litter_box_count smallint not null check(litter_box_count between 1 and 4),observation_context text not null check(observation_context in ('NEAR_BOX','ENTER_ROOM','FIXED_SPOT')),timezone text not null default 'Asia/Taipei',completed_at timestamptz not null default now());
create table public.baseline_snapshots(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users(id) on delete cascade,record_ids uuid[] not null,median_level numeric(2,1) not null,dominant_time_bucket public.time_bucket,rule_version text not null,created_at timestamptz not null default now());
create table public.improvements(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users(id) on delete cascade,type public.improvement_type not null,note varchar(80),status text not null check(status in ('ACTIVE','ENDED','CANCELLED')),started_at timestamptz not null default now(),ended_at timestamptz,baseline_snapshot_id uuid not null references public.baseline_snapshots(id),created_at timestamptz not null default now());
create unique index one_active_improvement_per_user on public.improvements(user_id) where status='ACTIVE';
create table public.odor_records(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users(id) on delete cascade,improvement_id uuid references public.improvements(id) on delete set null,odor_level smallint not null check(odor_level between 0 and 3),recorded_at timestamptz not null default now(),local_date date not null,time_bucket public.time_bucket not null,special_event_type public.special_event_type,special_event_note varchar(40),is_valid_for_analysis boolean not null default true,source_event_id text unique not null,created_at timestamptz not null default now());
create table public.analysis_results(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users(id) on delete cascade,improvement_id uuid not null references public.improvements(id) on delete cascade,result_code text not null,baseline_count int not null,post_count int not null,baseline_median numeric(2,1),post_median numeric(2,1),delta numeric(3,1),lower_ratio numeric(5,4),special_event_ratio numeric(5,4),time_bucket_mismatch_ratio numeric(5,4),median_interval_hours numeric,reason_codes jsonb not null default '[]',rule_version text not null,calculated_at timestamptz not null default now());
create table public.webhook_events(webhook_event_id text primary key,event_type text not null,received_at timestamptz not null default now(),processed_at timestamptz,status text not null,error_code text,payload_sha256 text not null);
create table public.user_consents(user_id uuid primary key references public.users(id) on delete cascade,privacy_version text not null,accepted_at timestamptz not null default now(),withdrawn_at timestamptz,source text not null);
create table public.deletion_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users(id) on delete cascade,status text not null check(status in ('PENDING','CANCELLED','PROCESSING','COMPLETED','FAILED')),requested_at timestamptz not null default now(),completed_at timestamptz,failure_reason text);
create unique index one_pending_deletion_per_user on public.deletion_requests(user_id) where status in ('PENDING','PROCESSING');
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_type text not null,actor_id text,action text not null,target_type text not null,target_id text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
alter table public.users enable row level security;alter table public.households enable row level security;alter table public.baseline_snapshots enable row level security;alter table public.improvements enable row level security;alter table public.odor_records enable row level security;alter table public.analysis_results enable row level security;alter table public.webhook_events enable row level security;alter table public.user_consents enable row level security;alter table public.deletion_requests enable row level security;alter table public.audit_logs enable row level security;
create policy users_own on public.users for select to authenticated using ((select auth.uid())=auth_user_id);
create policy households_own on public.households for all to authenticated using (user_id in(select id from public.users where auth_user_id=(select auth.uid()))) with check(user_id in(select id from public.users where auth_user_id=(select auth.uid())));
create policy records_own on public.odor_records for all to authenticated using (user_id in(select id from public.users where auth_user_id=(select auth.uid()))) with check(user_id in(select id from public.users where auth_user_id=(select auth.uid())));
create policy improvements_own on public.improvements for all to authenticated using (user_id in(select id from public.users where auth_user_id=(select auth.uid()))) with check(user_id in(select id from public.users where auth_user_id=(select auth.uid())));
create policy snapshots_own on public.baseline_snapshots for select to authenticated using (user_id in(select id from public.users where auth_user_id=(select auth.uid())));
create policy results_own on public.analysis_results for select to authenticated using (user_id in(select id from public.users where auth_user_id=(select auth.uid())));
create policy consents_own on public.user_consents for select to authenticated using (user_id in(select id from public.users where auth_user_id=(select auth.uid())));
create policy deletion_own on public.deletion_requests for select to authenticated using (user_id in(select id from public.users where auth_user_id=(select auth.uid())));
revoke all on public.webhook_events,public.audit_logs from anon,authenticated;
